// The reasoning behind every number.
// lv: 1 = meta-analysis or guideline built on trials, 2 = trials or large cohorts, 3 = small, indirect or n-of-1.
// g: what the evidence is. b(): the explanation, using your numbers. s: sources.
const LEVEL = ['', 'Strong', 'Moderate', 'Limited'];
const EVID = {
  kcal: { t: 'Calorie target', lv: 2, g: 'Validated equation, then your own data',
    b: () => { const T = targets(), M = T.model; return `Resting energy by Mifflin-St Jeor: <b>${fmt(T.bmr)} kcal</b>. Daily burn by formula, from steps and training: <b>${fmt(T.formula)} kcal</b>.${M.E != null ? ` Burn learned from your scale and your log: <b>${fmt(M.E)} kcal</b>, ±${fmt(1.96 * M.sd)} (95%).` : ''}<br><br>The equation misses by 10–15% in individuals, so the target moves from the formula to your own burn as its interval narrows: today it leans <b>${Math.round(T.trust * 100)}%</b> on your data (fully at ±150 kcal or better), and never further than 25% from the formula.<br><br>Daily burn <b>${fmt(T.tdee)}</b> less a deficit of <b>${fmt(T.deficit)}</b> gives <b>${fmt(T.live)} kcal</b>. The deficit is your pace times the energy in a kilogram of <i>your</i> change (${fmt(T.rho)} kcal/kg, see ${why('burn', 'the burn')}). ${T.locked ? `Your target is held at <b>${fmt(T.kcal)} kcal</b> until ${dateLabel(T.next, { weekday: 'long' })}, so it does not wobble with each day's steps. ${why('lock', 'Why weekly')}` : ''}`; },
    s: ['Mifflin MD, et al. Am J Clin Nutr. 1990;51:241–7', 'Hall KD, et al. Lancet. 2011;378:826–37', 'Sanghvi A, et al. Am J Clin Nutr. 2015;102:353–8'] },
  rate: { t: 'How fast to lose', lv: 2, g: 'Randomised trial, 24 athletes; review',
    b: () => { const P = PACE[S.settings.pace]; return `Losing 0.7% of body weight a week while lifting preserved and slightly increased lean mass. Losing 1.4% a week did not, and the slower group gained more strength. Reviews of dieting lifters land on 0.5–1% a week.<br><br>Your pace is <b>${P[0].toLowerCase()}</b>${P[1] ? `: ${P[1]}% a week, about ${r1(P[1] / 100 * targets().wt)} kg` : ''}. Change it in You › Goal. If the trend drops faster than 1% a week, the app tells you to eat more.`; },
    s: ['Garthe I, et al. Int J Sport Nutr Exerc Metab. 2011;21:97–104', 'Helms ER, et al. J Int Soc Sports Nutr. 2014;11:20'] },
  protein: { t: 'Protein target', lv: 1, g: 'Meta-analysis, 49 trials, 1,863 people',
    b: () => { const T = targets(); return `Muscle gain from resistance training stops improving above about 1.6 g of protein per kg a day. Fat mass does not need protein, so the app uses an adjusted weight of ${Math.round(T.adj)} kg: 1.6 × ${Math.round(T.adj)} ≈ <b>${T.protein} g</b>. In a deficit, higher protein plus lifting kept more lean mass in a controlled trial.<br><br>Two plates of poli, bhaji and varan give about 30–40 g. That gap is why whey, soya, usal and dahi carry this plan.`; },
    s: ['Morton RW, et al. Br J Sports Med. 2018;52:376–84', 'Longland TM, et al. Am J Clin Nutr. 2016;103:738–46'] },
  spread: { t: 'Protein at each meal', lv: 2, g: 'Review of feeding studies',
    b: () => { const T = targets(); return `Muscle protein synthesis responds to each meal, and about 0.4 g per kg per meal saturates the response. Spread across three or four meals, that is <b>${T.perMeal} g</b> at each main meal for you. A 15 g breakfast and a 70 g dinner add up to the same total but give the muscle fewer chances to build.<br><br>The daily total matters most; spreading it is the refinement.`; },
    s: ['Schoenfeld BJ, Aragon AA. J Int Soc Sports Nutr. 2018;15:10', 'Areta JL, et al. J Physiol. 2013;591:2319–31'] },
  fibre: { t: 'Fibre', lv: 2, g: 'National recommendation',
    b: () => 'ICMR-NIN sets fibre at 15 g per 1,000 kcal, about 30 g a day. Bhakri, usal, palebhaji and fruit get you there; maida and polished rice do not. Fibre and protein are also what keep you full on fewer calories.',
    s: ['ICMR-NIN. Nutrient Requirements for Indians, 2020', 'ICMR-NIN. Dietary Guidelines for Indians, 2024'] },
  logging: { t: 'Complete days only', lv: 2, g: 'Controlled study with doubly labelled water',
    b: () => 'People with obesity who believed they ate under 1,200 kcal under-reported intake by 47% on average when measured with doubly labelled water. A day with one meal missing looks exactly like a big deficit, so the burn estimate only uses days that look complete: at least two of breakfast, lunch and dinner logged and over 1,000 kcal. Tap the line under your meals to mark a day as incomplete yourself.',
    s: ['Lichtman SW, et al. N Engl J Med. 1992;327:1893–8'] },
  waist: { t: 'Waist matters more than BMI', lv: 2, g: 'Indian consensus; meta-analysis of 31 studies',
    b: () => 'At the same BMI, Asian Indians carry more body fat, and more of it around the abdomen, than Europeans. The Indian cut-offs are lower: BMI 23 overweight, 25 obese; waist 90 cm for men, 80 cm for women. Across populations, a waist above half your height predicted diabetes and cardiovascular risk better than BMI did.',
    s: ['Misra A, et al. J Assoc Physicians India. 2009;57:163–70', 'WHO Expert Consultation. Lancet. 2004;363:157–63', 'Ashwell M, et al. Obes Rev. 2012;13:275–86'] },
  project: { t: 'Your waist per kilogram', lv: 3, g: 'Your own measurements: a projection, not a promise',
    b: () => { const P = projection(); return `Each waist measurement is paired with your smoothed weight on that day, and a straight line is fitted through the pairs. ${P.perKg != null ? `So far your waist has moved <b>${r1(P.perKg)} cm per kg</b> (${P.n} measurements).` : 'It needs three waist measurements across at least 2 kg of change.'} Projecting forward assumes the line stays straight and the current rate holds; both drift, so the dates move as you log.`; },
    s: ['Ross R, et al. Nat Rev Endocrinol. 2020;16:177–89'] },
  steps: { t: 'Step goal', lv: 2, g: 'Meta-analysis of 15 cohorts, 47,471 adults',
    b: () => { const T = targets(); return `Mortality fell steadily with more daily steps and levelled off around 8,000–10,000 in adults under 60. Your goal sits 1,000 above your recent average and climbs to 8,000; past that it holds you where you are, because the curve is flat. Today it is <b>${fmt(T.stepGoal)}</b>.`; },
    s: ['Paluch AE, et al. Lancet Public Health. 2022;7:e219–28'] },
  sleep: { t: 'Sleep and fat loss', lv: 3, g: 'Crossover trial, 10 adults: small, direction consistent',
    b: () => 'On an identical calorie deficit, 5.5 hours in bed instead of 8.5 cut the share of weight lost as fat by 55% and raised hunger; the lost weight came from lean mass instead. Across 11 trials, short sleep raised next-day intake by about 385 kcal. Residency limits hours; a fixed wake time is the part you can control.',
    s: ['Nedeltcheva AV, et al. Ann Intern Med. 2010;153:435–41', 'Al Khatib HK, et al. Eur J Clin Nutr. 2017;71:614–24'] },
  regular: { t: 'Sleep timing', lv: 2, g: 'Cohort of 60,977 adults with accelerometers',
    b: () => 'Sleep regularity predicted mortality more strongly than sleep duration in UK Biobank. The app reports the spread of your sleep midpoint (halfway between falling asleep and waking) across the last 14 nights; under 30 minutes is regular, over 60 is irregular. Night duties will push it up; a fixed wake time on off days pulls it back.',
    s: ['Windred DP, et al. Sleep. 2024;47:zsad253', 'Phillips AJK, et al. Sci Rep. 2017;7:3216'] },
  stages: { t: 'Sleep stages from a watch', lv: 2, g: 'Seven devices against polysomnography',
    b: () => 'Consumer trackers are good at telling sleep from wake and at total sleep time. They are much weaker at deep and REM sleep, where agreement with a sleep lab was moderate at best. The app shows your stage split for interest but never makes a recommendation from it; duration, timing and sleeping heart rate carry the decisions.',
    s: ['Chinoy ED, et al. Sleep. 2021;44:zsaa291', 'de Zambotti M, et al. Med Sci Sports Exerc. 2019;51:1538–57'] },
  lift: { t: 'Training plan', lv: 1, g: 'Two meta-analyses',
    b: () => `Muscle growth rises with weekly sets per muscle, and training a muscle at least twice a week beats once. Your programme is <b>${esc(PROGRAMS[S.settings.prog].n.toLowerCase())}</b>, trained in openGym from the plan file Health makes. Stop 1–3 reps short of failure. ${why('block', 'How the block is set up')}<br><br>${S.profile.shoulder ? 'With shoulder care on, pressing is neutral-grip or angled, laterals stop at shoulder height, and overhead pressing and flyes are swapped for movements that never reach the provocative end range.' : 'Turn on shoulder care in You › Training if a shoulder is sore: the plan then keeps every exercise out of the positions that provoke it.'}`,
    s: ['Schoenfeld BJ, et al. J Sports Sci. 2017;35:1073–82', 'Schoenfeld BJ, et al. Sports Med. 2016;46:1689–97'] },
  volume: { t: 'Sets per muscle', lv: 1, g: 'Meta-analysis; maintenance trial',
    b: () => 'Ten or more hard sets per muscle a week produced more growth than fewer than five. Keeping muscle needs far less: a third of the training volume maintained size and strength for months in young adults. In a deficit, 4 or more sets per muscle a week protects what you have; about 10 builds.<br><br>Each set counts fully for the muscle an exercise is for and half for a muscle it trains on the way: a row is a whole set for the back and half a set for the biceps. That half is a convention, not a measured number; it stops the map from claiming a row built your arms.',
    s: ['Schoenfeld BJ, et al. J Sports Sci. 2017;35:1073–82', 'Bickel CS, et al. Med Sci Sports Exerc. 2011;43:1177–87'] },
  e1rm: { t: 'Strength from your sets', lv: 2, g: 'Validation in trained and untrained lifters',
    b: () => 'Each set is turned into an estimated one-rep maximum with the Epley formula: weight × (1 + reps ÷ 30). It is accurate within a few percent below about 10 reps and drifts above 15, so higher-rep sets are left out. Comparing best estimates across sessions shows strength trend without ever testing a true maximum.',
    s: ['LeSuer DA, et al. J Strength Cond Res. 1997;11:211–3'] },
  trimp: { t: 'Training load', lv: 2, g: 'Heart-rate load methods; a critique of the acute:chronic ratio',
    b: () => { const H = hrProfile(); return `Each session's load is Edwards' zone TRIMP, a simple form of Banister's training impulse: minutes at 50–59% of maximum heart rate count once, 60–69% twice, and so on up to five times at 90% and above. Your maximum is <b>${H.max}</b> bpm (${H.maxSrc === 'seen' ? 'the highest the strap has seen' : 'from your age, until the strap sees higher'}).<br><br>Only heart rate that is really there counts: the strap's trace, or the watch's once it has been matched to the strap. A session without either, lifting logged with no timed workout, or a strap session saved before traces were kept, is left out and named, not guessed.<br><br>The last 7 days are shown beside your usual week over the last four, and monotony (Foster: the week's average daily load divided by its spread; above about 2, every day is alike) as context. The ratio of this week to the usual is not shown as an injury risk: re-analysis found that reading does not hold up.`; },
    s: ['Edwards S. The Heart Rate Monitor Book. 1993', 'Banister EW. In: Physiological Testing of the High-Performance Athlete. 1991:403–24', 'Foster C. Med Sci Sports Exerc. 1998;30:1164–8', 'Impellizzeri FM, et al. Int J Sports Physiol Perform. 2020;15:907–13'] },
  zones: { t: 'Heart-rate zones', lv: 1, g: 'WHO guideline; ACSM position stand',
    b: () => { const H = hrProfile(); return `Intensity is a share of your heart-rate reserve, the gap between resting and maximum (Karvonen): moderate is 40–59%, vigorous 60–89%. For you: moderate <b>${H.zones[0]}–${H.zones[1] - 1}</b>, vigorous <b>${H.zones[1]}–${H.zones[2] - 1}</b> bpm.<br><br>Maximum: ${H.maxSrc === 'seen' ? `<b>${H.max}</b>, the highest your chest strap has recorded, which beats the formula's ${H.est}` : `<b>${H.max}</b> by 208 − 0.7 × age; formulas miss by about 10 bpm either way, so the first workout that goes higher replaces it`}. Resting: <b>${H.rest}</b>, ${H.restSrc}.<br><br>WHO advises 150–300 moderate minutes a week, vigorous counting double, and muscle-strengthening on 2 or more days.`; },
    s: ['Bull FC, et al. Br J Sports Med. 2020;54:1451–62', 'Garber CE, et al. Med Sci Sports Exerc. 2011;43:1334–59', 'Tanaka H, et al. J Am Coll Cardiol. 2001;37:153–6', 'Karvonen MJ, et al. Ann Med Exp Biol Fenn. 1957;35:307–15'] },
  hrv: { t: 'Morning HRV', lv: 2, g: 'Randomised trials of HRV-guided training',
    b: () => 'RMSSD is beat-to-beat variation driven by vagal tone, analysed on the log scale. A single morning means little. The app follows the method used in the trials: your normal range is your baseline mean ± half a standard deviation (the smallest worthwhile change), and it is your 7-day rolling average, not one day, that is compared with it. A 7-day average below range means ease off; inside range, train as planned.<br><br>The day-to-day wobble (coefficient of variation) is shown too: a rising wobble often precedes the drop. One minute of recording after one minute of settling agrees well with longer recordings; you can record two to five minutes instead, which adds the low-frequency band and a steadier breathing rate. Keep the same length and position every morning, because both change the numbers. Measure on waking, lying down, before coffee.<br><br>Morning heart rate from the same checks is read alongside: HRV down with heart rate up is the common pattern of fatigue, illness, short sleep or alcohol; HRV down with heart rate also down is a weaker and less clear signal, described in highly trained athletes as parasympathetic saturation rather than fatigue. The minute of beats is kept with each reading.',
    s: ['Vesterinen V, et al. Med Sci Sports Exerc. 2016;48:1347–54', 'Plews DJ, et al. Sports Med. 2013;43:773–81', 'Plews DJ, et al. Eur J Appl Physiol. 2012;112:3729–41', 'Esco MR, Flatt AA. J Sports Sci Med. 2014;13:535–41'] },
  ill: { t: 'Early sign of illness', lv: 3, g: 'Observational studies with wearables',
    b: () => `In people wearing smartwatches, resting heart rate rose above their own baseline in most infections, often a day or more before symptoms (Mishra 2020, Radin 2020), and HRV fell (Hirten 2021). The app looks for both together on each of the last two nights, each against your own data only: resting heart rate at least 3 bpm and 1.5 standard deviations above your usual, and HRV below your normal range (your mean ± one standard deviation, on the log scale). Your usual is the four weeks before the last week, at least ${ILL_BASE} values, from the same source (strap with strap, watch with watch); the watch's overnight HRV only from nights it was worn through.<br><br>Training hard, alcohol, a late meal, heat, travel or a short night can do the same. The notice is only a reason to take it easy; it is not a diagnosis. If you feel unwell, or it goes on, see a doctor.`,
    s: ['Mishra T, et al. Nat Biomed Eng. 2020;4:1208–20', 'Radin JM, et al. Lancet Digit Health. 2020;2:e85–93', 'Hirten RP, et al. J Med Internet Res. 2021;23:e26107'] },
  spo2: { t: 'Blood oxygen in sleep', lv: 3, g: 'A small study of healthy sleepers; device checks',
    b: () => `In healthy adults, blood oxygen through the night averages about 95–97%, with brief dips lower (Gries 1996). Nights that average under about ${O2_LOW}% are uncommon without a breathing or lung problem, so when that happens on ${O2_REPEAT} or more nights it is worth mentioning to a doctor, who can arrange a proper sleep or oxygen study.<br><br>Wrist SpO2 is not medical grade: it can miss by several points against a clinical oximeter (Pipek 2021), and reads low with a loose strap, cold hands or lying on the arm. So the app uses only the readings inside the night's main sleep, only nights with at least ${O2_READS} of them and the watch worn through, and says nothing until it has ${O2_NIGHTS} such nights in the last two weeks. It is a reason to ask, not a finding.`,
    s: ['Gries RE, Brooks LJ. Chest. 1996;110:1489–92', 'Pipek LZ, et al. Sci Rep. 2021;11:18901'] },
  rhr: { t: 'Resting and sleeping heart rate', lv: 3, g: 'Reviews of athlete monitoring',
    b: () => 'Resting heart rate is compared with your own previous three weeks: a sustained rise of about 5 bpm or more accompanies illness, short sleep, alcohol or accumulated fatigue. Sleeping heart rate, the average across your main sleep from the watch, moves the same way and is measured every night without effort. Days with a morning check use the strap; other days use the watch, corrected by the offset the app has learned between them.',
    s: ['Buchheit M. Front Physiol. 2014;5:73'] },
  devices: { t: 'Watch against strap', lv: 2, g: 'Method-comparison statistics; validation studies',
    b: () => 'The H9 is a chest strap that reads the heart\'s electrical signal; its sibling, the Polar H10, matched a Holter ECG beat for beat. A wrist watch reads blood flow with light, which is close at rest and drifts during exercise, most of all in lifting and with arm movement.<br><br>When you wear both, the app pairs the readings and reports agreement the standard way (Bland–Altman): the average difference (bias) and the range that 95% of single readings fall within. After 5 paired mornings the bias is used to put watch resting heart rate on the strap\'s scale; after 3 paired workouts, to correct watch workout zones by a fixed shift. Wrist error grows with effort and arm movement (Bent 2020), so once 6 paired workouts span at least 30 bpm, watch workout heart rate is mapped to the strap by a straight line instead (least squares), and its residual error is shown in Data checks. Wrist calorie estimates are shown but never used: none of seven watches tested came within 20% for energy burned.',
    s: ['Bland JM, Altman DG. Lancet. 1986;1:307–10', 'Gilgen-Ammann R, et al. Eur J Appl Physiol. 2019;119:1525–32', 'Bent B, et al. NPJ Digit Med. 2020;3:18', 'Boudreaux BD, et al. Med Sci Sports Exerc. 2018;50:624–33', 'Shcherbina A, et al. J Pers Med. 2017;7:3'] },
  balance: { t: 'Energy ledger', lv: 2, g: 'Intake-balance, validated against doubly labelled water',
    b: () => { const T = targets(); return `Intake on complete days, minus the energy your body change represents, is the energy you burn. Health works it out every day with the energy model (${why('burn', 'how')}), not from a fixed 7,700 kcal per kilogram: at your size a kilogram of change holds about <b>${fmt(T.rho)} kcal</b>.<br><br>When the learned burn sits far below the formula (${fmt(T.formula)} kcal), unlogged oil, snacks or outside meals are the commonest reason, not a slow metabolism. It does not matter for the target: the target is built on the same log, so it lands where it should either way.`; },
    s: ['Hall KD, et al. Lancet. 2011;378:826–37', 'Sanghvi A, et al. Am J Clin Nutr. 2015;102:353–8', 'Thomas DM, et al. J Acad Nutr Diet. 2014;114:857–61'] },
  burn: { t: 'How your burn is learned', lv: 2, g: 'Model validated against DLW/DXA in a 2-year trial; Kalman filter',
    b: () => { const M = energyModel(); return `Every morning weigh-in and every completely logged day go into a Kalman filter that tracks two hidden numbers: your true weight under the scale's noise, and the energy you burn a day. Weight tomorrow = weight today + (eaten − burned) ÷ the energy in a kilogram of change; the burn itself may drift slowly (adaptation, a new routine).<br><br>A kilogram of change is not 7,700 kcal for everyone: the share that is fat depends on how much fat there is (Forbes), and fat holds 9,440 kcal/kg against 1,816 for lean tissue with its water (Hall). Your body fat, <b>${r1(M.bf?.pct ?? bodyFat().pct)}%</b>, comes from ${(M.bf || bodyFat()).src === 'rfm' ? 'your waist and height (Relative Fat Mass, calibrated against DXA in 12,581 adults)' : 'your BMI and age (add a waist measurement for a better estimate)'}; so about <b>${Math.round((M.fatShare ?? 0.7) * 100)}%</b> of a change is fat and a kilogram holds <b>${fmt(M.rho ?? 7400)} kcal</b>.<br><br>Days without a complete log add uncertainty, not bias. The scale's own day-to-day noise is measured from your weigh-ins (yours: ±${r1(M.noise ?? 0.7)} kg). The same principle, run with a metabolic model on weigh-ins alone, came within 40 kcal/d of doubly labelled water on average over two years in the CALERIE trial, and within 215 kcal/d for individuals.<br><br>${burnWords(M)}`; },
    s: ['Sanghvi A, et al. Am J Clin Nutr. 2015;102:353–8', 'Hall KD. Int J Obes. 2008;32:573–6', 'Forbes GB. Ann N Y Acad Sci. 2000;904:359–65', 'Woolcott OO, Bergman RN. Sci Rep. 2018;8:10980'] },
  score: { t: 'The recovery number', lv: 3, g: 'Summary of signals each with their own evidence',
    b: () => 'The zone comes from the verdict, by the rules the HRV-guided training trials used: the 7-day average of ln RMSSD against your own normal range (± half a standard deviation), read with resting heart rate, sleep and breathing. Green 67–99: train as planned. Yellow 34–66: train, but listen. Red 1–33: keep it easy.<br><br>Where in its zone a day sits comes from how far each signal is from your normal, in standard deviations, weighted by the evidence behind it: HRV 45%, sleep 25%, resting heart rate 20%, breathing in sleep 10%. Each part is shown beside the number. It is a summary for the eye, not a new measurement, and it is not a medical test.',
    s: ['Plews DJ, et al. Int J Sports Physiol Perform. 2013;8:688–94', 'Javaloyes A, et al. Int J Environ Res Public Health. 2021;18:10285', 'Buchheit M. Front Physiol. 2014;5:73', 'Natarajan A, et al. Lancet Digit Health. 2020;2:e650–7'] },
  sri: { t: 'Sleep Regularity Index', lv: 2, g: 'Defined against circadian phase; prospective cohort of 60,977',
    b: () => 'The chance of being in the same state, asleep or awake, at any two moments 24 hours apart, scaled from −100 to 100: 100 is the same sleep every day. Worked out minute by minute from when each night started and ended. Irregular sleepers had later melatonin onset (Phillips 2017). In UK Biobank the median was 81 (middle half 74–86), and regularity predicted all-cause mortality more strongly than sleep length (Windred 2024). A fixed wake time, light in the morning and the same lights-out on days off are what move it.',
    s: ['Phillips AJK, et al. Sci Rep. 2017;7:3216', 'Windred DP, et al. Sleep. 2024;47:zsad253'] },
  comp: { t: 'Reading body composition', lv: 3, g: 'Inference from three measurements, not a scan',
    b: () => 'The app has no direct measure of fat or muscle. It reads three things together: weight trend, waist and strength. Weight and waist falling while strength holds is the pattern expected when the loss is fat. Weight falling with strength is the warning sign. A smart-scale body-fat figure, if Health Connect has one, is shown but not trusted on its own: bioimpedance shifts with hydration by several percentage points.',
    s: ['Helms ER, et al. J Int Soc Sports Nutr. 2014;11:20', 'Kyle UG, et al. Clin Nutr. 2004;23:1226–43'] },
  links: { t: 'Links in your own data', lv: 3, g: 'n-of-1 observation: association, not cause',
    b: () => 'Each pair is read the way a single-person study should be. Both series are taken as their deviation from their own 15-day running mean, so two things that simply drift together over months (weight down, HRV up) are not mistaken for one driving the other. The lag follows the physiology: last night’s sleep with this morning’s HRV, today’s food with tomorrow’s scale. Daily data are autocorrelated, so the effective number of days is cut by the lag-1 autocorrelation of both series, and the interval widens to match.<br><br>Effects are quoted in real units with a 95% interval. <b>Clear</b>: the interval leaves out zero. <b>Hint</b>: a moderate link the data cannot yet confirm. Nothing is read below 14 paired days. These are still associations in one person, open to confounding by duty hours, festivals and everything else: they suggest what to test, and each one says how.',
    s: ['Lillie EO, et al. Per Med. 2011;8:161–73', 'Bartlett MS. J R Stat Soc. 1946;8:27–41', 'Schork NJ. Nature. 2015;520:609–11'] },
  progress: { t: 'When the weight goes up', lv: 2, g: 'Randomised trial; meta-analysis of rep prediction',
    b: () => 'Double progression: stay at a load and add reps until every set reaches the top of the range, then add the smallest step of weight and start again from the bottom. Adding reps and adding load built the same muscle in a 2022 trial, so neither is the "real" progression.<br><br>The decision uses reps you actually completed, never how hard a set felt: people misjudge reps in reserve by about a rep, more so far from failure. Three sessions in a row under the bottom of the range drops the load 10% so you build back instead of grinding.',
    s: ['Plotkin D, et al. PeerJ. 2022;10:e14142', 'Halperin I, et al. Sports Med. 2022;52:377–90'] },
  rest: { t: 'Rest between sets', lv: 2, g: 'Randomised trial; systematic review',
    b: () => 'Rest long enough that the next set is limited by the muscle, not by breathing. Three-minute rests built more strength and muscle than one-minute rests in trained men, and the review agrees for strength. The timer starts at 2½ minutes after exercises that work several big muscles and 1½ after small ones; change it in You › Training. The precise numbers are a convention: the trials are small and short.',
    s: ['Schoenfeld BJ, et al. J Strength Cond Res. 2016;30:1805–12', 'Grgic J, et al. Sports Med. 2018;48:137–51'] },
  shoulder: { t: 'Shoulder care', lv: 2, g: 'Placebo-controlled surgical trial; mechanics',
    b: () => 'Exercise is the first treatment for shoulder impingement pain: in a trial with a placebo operation, removing bone under the acromion did no better than the placebo. So the plan keeps training the shoulder and changes positions instead: no loaded overhead end range, no arms behind the body in a fly, laterals to shoulder height, and a five-minute cuff and shoulder-blade routine.<br><br>After a shoulder-loading exercise you can say how it felt. A niggle holds the load and shortens the range next time; pain swaps the exercise; pain twice in a row takes it out of the plan until you bring it back. Which exercises to avoid comes from joint mechanics rather than trials, and the app says so.',
    s: ['Beard DJ, et al. Lancet. 2018;391:329–38', 'Paavola M, et al. BMJ. 2018;362:k2860'] },
  lock: { t: 'Why the target holds for a week', lv: 3, g: 'Practical choice',
    b: () => 'Your burn estimate moves a little every day with steps and the weight trend. A target that changed every morning would be noise: nothing about your body changes in a day. So the calorie and protein targets are recalculated once a week, on Monday, and a single update never moves calories by more than 150 kcal. Changing your profile, pace or protein setting recalculates at once.',
    s: ['Hall KD, et al. Lancet. 2011;378:826–37'] },
  dfa: { t: 'Aerobic threshold from your beats', lv: 2, g: 'Validation against gas exchange and lactate; small studies',
    b: () => { const T = thresholds(); return `During cardio the strap sends every beat-to-beat interval. Every 30 seconds the app takes the last two minutes of them and works out <b>α1</b>, the short-term scaling exponent of detrended fluctuation analysis: how much each beat's timing depends on the ones before. At easy effort the pattern is well correlated (α1 near 1); as effort rises it breaks down, and a value of 0.75 has matched the first ventilatory threshold in recreational runners, people with heart disease, and the first lactate threshold in elite triathletes. 0.5 sits near the second threshold.<br><br>A threshold is estimated only when a session actually crosses 0.75: a straight line of α1 on heart rate through the windows between 0.5 and 1.1, at least six windows, 15 bpm of range and a clear negative relation. Missed beats bias α1, so a window with more than 5% corrected beats is dropped; under 3% the bias is small and the threshold moved by under a beat in testing. A chest strap is needed: wrist sensors do not give true beat-to-beat intervals.${T.length ? `<br><br>Yours so far: <b>${T.map(x => x.hr).join(', ')} bpm</b>, newest first.` : ''} The agreement in the studies is within a few beats on average but about ±15 bpm for an individual test, so three estimates that agree are worth more than one.`; },
    s: ['Rogers B, Gronwald T. Front Physiol. 2022;13:879071', 'Rogers B, et al. Sensors. 2021;21:821', 'Rogers B, et al. Sports. 2022;10:25', 'Rogers B, et al. J Clin Med. 2021;10:4075'] },
  night: { t: 'What the watch measures overnight', lv: 3, g: 'Wearable validation studies; an illness-detection cohort',
    b: () => 'Overnight HRV from a wrist sensor is measured asleep, from light rather than the heart\'s electrical signal, by the watch maker\'s own method. Some devices agree well with an ECG at rest and others badly; Amazfit has no independent validation that the app knows of. So the watch\'s HRV gets its own normal range, is never mixed with the strap\'s morning check, and on a day with no strap reading can only nudge the verdict to "listen to your body".<br><br>Breathing rate during sleep is steadier from night to night than HRV. In 2,745 people with COVID-19, breathing rate and heart rate rose and HRV fell with illness, often before symptoms. The app flags a night 1 or more breaths a minute above your usual and beyond twice your normal spread. Wrist SpO2 and VO2max are shown as interest only.',
    s: ['Stone JD, et al. Front Sports Act Living. 2021;3:585870', 'Natarajan A, et al. NPJ Digit Med. 2020;3:156'] },
  block: { t: 'The training block sent to openGym', lv: 2, g: 'Randomised trial; meta-analysis; HRV-guided training trials',
    b: () => 'The plan file carries Health\'s programme as openGym routines, run as a rotation (A, B, C, A...), so a missed day moves the plan along instead of skipping a session. Each week shows an effort target of RPE 8, about two reps left before failure: muscle growth rises as sets get closer to failure, while going to failure every set adds fatigue with little extra, which matters more in a calorie deficit.<br><br>There is <b>no planned deload week</b>. In a randomised trial, a one-week break in the middle of a nine-week programme gave the same muscle growth and less strength gain than training straight through. Easing off is done when the data asks for it instead: three stalled sessions drop a load 10%, and a 7-day HRV average below your range turns the day into an easy one (one set fewer, last time\'s loads), the way the HRV-guided trials did it. Each exercise travels with up to three backups from openGym\'s catalogue, picked by hand for the same main muscle and kept clear of the shoulder\'s provocative positions.',
    s: ['Coleman M, et al. PeerJ. 2024;12:e16777', 'Refalo MC, et al. Sports Med. 2023;53:649–65', 'Vesterinen V, et al. Med Sci Sports Exerc. 2016;48:1347–54'] },
  checkin: { t: 'Measuring regularly', lv: 2, g: 'Randomised trial of daily weighing; WHO measurement protocol',
    b: () => 'In a six-month randomised trial, daily weighing with feedback led to clearly more weight loss than a delayed-start control group, and did not raise anxiety or disordered eating. Weigh at the same time and in the same state each day: the trend line does the averaging. Waist changes slowly, so once a week is enough; measure midway between the lowest rib and the top of the hip bone at the end of a normal breath out, the WHO protocol, and always at the same spot. The morning HRV check is what builds your normal range, and reminders on the phone make all three a habit at the time you choose.',
    s: ['Steinberg DM, et al. Obesity. 2013;21:1789–97', 'WHO. Waist circumference and waist–hip ratio: report of a WHO expert consultation. Geneva; 2011'] },
  trend: { t: 'Reading the scale', lv: 2, g: 'Robust statistics; energy-balance models',
    b: () => 'Body weight swings 1–2 kg in a day on water, salt and food in the gut. The trend line smooths each weigh-in toward the last, so a single reading moves it only a tenth of the way. The weekly rate uses the median of the slopes between every pair of weigh-ins in the last three weeks (the Theil–Sen estimate) rather than a straight least-squares line, so one festival dinner or a missed reading cannot swing it. It needs 6 weigh-ins across 10 days.',
    s: ['Sen PK. J Am Stat Assoc. 1968;63:1379–89', 'Hall KD, et al. Lancet. 2011;378:826–37'] },
  metrics: { t: 'Every HRV measure, and how the beats are cleaned', lv: 2, g: 'International standards; validated methods',
    b: () => 'Each reading starts with the beat-to-beat intervals the strap times from your ECG. A beat is compared with the median of the 11 around it, and the distance allowed adapts to how variable your beats really are at that moment (Lipponen & Tarvainen), never tighter than 12%. A fixed rule would wrongly "correct" real beats during slow breathing, when heart rate swings by 20 bpm or more with every breath. A missed beat is split in two, an extra one merged, an early beat and its pause evened out, anything else replaced by the local median; the share that needed it is the reading\'s quality, and under 80% nothing is saved.<br><br><b>RMSSD</b> (and its log, ln RMSSD) is beat-to-beat variation, driven by the vagus nerve: the measure the training trials used. <b>SDNN</b> is all variability together. <b>pNN50</b> is the share of beats differing from the last by more than 50 ms. On the <b>Poincaré plot</b>, each interval against the next, SD1 is the beat-to-beat width (RMSSD ÷ √2) and SD2 the slower swings.<br><br>The <b>spectrum</b> uses the Lomb–Scargle method, which works on the uneven timing of real beats without resampling. HF (0.15–0.4 Hz) follows breathing and the vagus; LF (0.04–0.15 Hz) needs two minutes and mixes both branches of the nervous system with blood-pressure control, so LF/HF is not a "stress balance", whatever some apps say: it moves as much with how you breathe.<br><br><b>Breathing rate</b> is the strongest rhythm in your beats between 6 and 30 a minute: heart rate rises with each breath in and falls with each breath out. It agrees well with measured breathing at rest, less well when breathing is irregular.',
    s: ['Task Force of the ESC and NASPE. Circulation. 1996;93:1043–65', 'Shaffer F, Ginsberg JP. Front Public Health. 2017;5:258', 'Lipponen JA, Tarvainen MP. J Med Eng Technol. 2019;43:173–81', 'Laguna P, et al. IEEE Trans Biomed Eng. 1998;45:698–715', 'Schäfer A, Kratky KW. Ann Biomed Eng. 2008;36:476–85', 'Brennan M, et al. IEEE Trans Biomed Eng. 2001;48:1342–7', 'Plews DJ, et al. Int J Sports Physiol Perform. 2017;12:1324–8'] },
  breathe: { t: 'Slow breathing', lv: 2, g: 'Two meta-analyses; mechanism well established',
    b: () => 'Breathing slowly, around six breaths a minute, makes heart rate rise and fall with each breath far more than usual, and the baroreflex, the reflex that steadies blood pressure, swings with it. Across 223 studies, slow breathing raised vagally mediated HRV during the practice, whatever the exact technique. Across 58 trials of HRV biofeedback (slow breathing at your own resonance rate, with feedback, practised regularly), anxiety, depressed mood, stress and some measures of performance improved, with small to moderate effects.<br><br>With the strap on, the app shows what is happening: your heart rate beat by beat, the swing per breath, and how much of your variability sits at the rate you are breathing. Breathe gently through the nose, a little longer out than in, and never so deep that you feel light-headed.<br><br>What it does not show: these are effects during and soon after practice. The app keeps every session, so you can see your own swing grow over weeks, but your morning HRV is what tracks recovery.',
    s: ['Laborde S, et al. Neurosci Biobehav Rev. 2022;138:104711', 'Lehrer P, et al. Appl Psychophysiol Biofeedback. 2020;45:109–29', 'Lehrer PM, Gevirtz R. Front Psychol. 2014;5:756', 'Zaccaro A, et al. Front Hum Neurosci. 2018;12:353'] },
  sigh: { t: 'Cyclic sighing and box breathing', lv: 2, g: 'Randomised trial for cyclic sighing; box breathing by analogy only',
    b: () => 'In a one-month randomised trial of about a hundred adults doing five minutes a day, <b>cyclic sighing</b> (a breath in, a short second breath in on top, then a long slow breath out) improved mood more than mindfulness meditation, and lowered breathing rate at rest. Box breathing and cyclic hyperventilation were the other arms; the difference between breathing methods was modest, and all improved mood.<br><br><b>Box breathing</b> (in, hold, out, hold, four seconds each) is slow breathing at under four breaths a minute with pauses. It has little direct trial evidence of its own; what it shares with the others is the slow pace, which is well supported. Use whichever you will actually do.',
    s: ['Balban MY, et al. Cell Rep Med. 2023;4:100895', 'Laborde S, et al. Neurosci Biobehav Rev. 2022;138:104711'] },
  rf: { t: 'Your resonance rate', lv: 2, g: 'Protocol and mechanism studies; practical guide',
    b: () => `Heart rate and blood pressure each have their own rhythm. At one breathing rate, different for each person and usually between 4.5 and 6.5 breaths a minute, breathing drives both in step and the swing in heart rate is largest: the resonance frequency. It depends mainly on blood volume, so taller people tend to resonate slower, and it is stable over months.<br><br>The finder runs the standard protocol: two minutes at each of 6.5, 6, 5.5, 5 and 4.5 breaths a minute. For each rate it measures the peak-to-trough swing of your heart rate per breath, the main criterion, and the height of the low-frequency peak; the largest swing wins, and a near tie goes to the stronger peak. ${S.meta.rf ? `Yours, found ${dateLabel(S.meta.rf.at)}: <b>${S.meta.rf.rate}</b> a minute.` : ''}`,
    s: ['Lehrer PM, et al. Appl Psychophysiol Biofeedback. 2000;25:177–91', 'Vaschillo EG, et al. Appl Psychophysiol Biofeedback. 2006;31:129–42', 'Shaffer F, Meehan ZM. Front Neurosci. 2020;14:570400'] },
  ortho: { t: 'The orthostatic test', lv: 3, g: 'Athlete monitoring studies',
    b: () => 'Standing up shifts blood to the legs; heart rate rises and vagal activity falls within seconds. How much it rises, and how HRV looks lying and standing, changes with accumulated fatigue: in elite endurance athletes, distinct patterns in both positions accompanied different kinds of fatigue, and standing measures sometimes caught what lying ones missed.<br><br>The test: 2½ minutes lying (the first 30 seconds settle), then stand on the cue and stay still for 2½ minutes. The app keeps lying heart rate and RMSSD, the peak in the first 45 seconds after standing, and standing heart rate and RMSSD after the first 30 seconds. There are no general cut-offs worth trusting: from the seventh test on, each is read against your own previous ones, and it is meant to be read alongside your morning check.',
    s: ['Schmitt L, et al. Front Physiol. 2015;6:343', 'Buchheit M. Front Physiol. 2014;5:73'] },
  live: { t: 'Live sessions: what a reading at any moment can and cannot say', lv: 2, g: 'Validation studies of the strap and of short recordings; measurement guidelines',
    b: () => 'A chest strap times each beat from the heart\'s electrical signal. Against a clinical ECG, the Polar H10 agreed almost beat for beat at rest and during exercise; the H9 has the same electronics on a simpler strap and fewer published tests, so wet the electrodes and keep it snug, and watch the share of clean beats: movement, a dry strap or a loose fit show there first.<br><br><b>What is shown live.</b> RMSSD, SDNN, pNN50 and the Poincaré widths are worked out over the last minute of beats, breathing rate from the rhythm in them, and α1 over the last two minutes. One minute is enough for RMSSD to agree closely with a five-minute recording at rest; SDNN and the frequency measures need longer, so a marked stretch is read from its last five minutes (or all of it, if shorter), the standard short-term window, and the frequency measures of a whole mixed session are not reported at all, because they assume the body stayed in one state.<br><br><b>How to read it.</b> HRV moves within seconds with posture, breathing, movement, food, caffeine and what you are thinking about. So a Live session answers "what happened in me during this", best seen as the change between two marked stretches under the same conditions, and against your own earlier stretches with the same mark (from the seventh on). It does not measure recovery: that stays with the morning check, taken the same way each day. α1 near 1 is normal at rest and easy effort and falls as effort rises; at rest it is shown for interest, not as a threshold.',
    s: ['Gilgen-Ammann R, et al. Eur J Appl Physiol. 2019;119:1525–32', 'Munoz ML, et al. PLoS One. 2015;10:e0138921', 'Shaffer F, et al. Front Neurosci. 2020;14:594880', 'Laborde S, et al. Front Psychol. 2017;8:213', 'Task Force of the ESC and NASPE. Circulation. 1996;93:1043–65'] },
  hrr: { t: 'Heart-rate recovery', lv: 2, g: 'Large cohort; systematic review in athletes',
    b: () => 'How far heart rate falls in the first minute after exercise reflects how quickly the vagus nerve takes back control. In 2,428 adults after an exercise test, a fall of 12 bpm or less in the first minute predicted higher mortality, independently of fitness. That was after a maximal test with a cool-down walk, so it is no cut-off for an ordinary session.<br><br>In athletes, recovery tends to get faster with improving fitness and can slow with accumulated fatigue, but it also depends on how hard the session ended. So it is most useful compared with your own, after similar sessions: stop, stand still with the strap on, breathe normally, and the app measures the drop from your last ten seconds of exercise to the end of the minute.',
    s: ['Cole CR, et al. N Engl J Med. 1999;341:1351–7', 'Daanen HAM, et al. Int J Sports Physiol Perform. 2012;7:251–60', 'Buchheit M. Front Physiol. 2014;5:73'] },
  markers: { t: 'The long game', lv: 2, g: 'Meta-analyses of prospective cohorts',
    b: () => 'Eight things that, across large cohorts followed for years, track how long people live and how many of those years are healthy: aerobic fitness, daily steps, resting heart rate, waist against height, sleep length and regularity, the gap between weekday and weekend sleep, strength training and active minutes. Each is worked out here from data the app already has, and read against the dose-response the studies found. Green is where the evidence puts the most benefit.<br><br>These are associations in observational studies: people who walk more also differ in other ways. Where trials exist they point the same way (exercise lowers resting heart rate and raises fitness; weight loss shrinks the waist), which is why the app ranks them by how much the cohorts saw, and shows the one worth the most first. None of it is a diagnosis.',
    s: ['Kodama S, et al. JAMA. 2009;301:2024–35', 'Paluch AE, et al. Lancet Public Health. 2022;7:e219–28', 'Zhang D, et al. CMAJ. 2016;188:E53–63', 'Momma H, et al. Br J Sports Med. 2022;56:755–63'] },
  fitness: { t: 'Fitness without a treadmill', lv: 2, g: 'Model from 4,260 adults with measured VO2peak; validated in another cohort',
    b: () => { const F = fitness(); return `Aerobic fitness (VO2peak) is one of the strongest single predictors of mortality: in 33 cohorts with 102,980 people, each 1 MET higher (3.5 ml/kg/min) went with <b>13% lower all-cause mortality</b>, and below 7.9 METs risk was 70% higher than at 10.9 or more.<br><br>Measuring it takes a maximal treadmill test. The HUNT study measured it directly in 4,260 healthy adults and found that age, waist, resting heart rate and leisure activity together explained 61% of it in men and 56% in women. The app uses that equation, with your waist, your 4-week resting heart rate on one consistent scale, and an activity index built from what you actually did (sessions a week, their median length, how hard by heart rate).${F.v != null ? `<br><br>Today: <b>${r1(F.v)} ml/kg/min</b> (${r1(F.mets)} METs). Resting heart rate ${Math.round(F.rhr)} from ${F.nR} days, waist ${r1(F.waist)} cm, ${r1(F.P.perWk)} sessions a week of about ${Math.round(F.P.min)} minutes, activity index ${r1(F.P.pa)} of 50.` : ''}<br><br>It is an estimate: 95% of people sit within about ±${S.profile.sex === 'f' ? 10 : 11} ml/kg/min of it. For tracking <i>change</i> it does better: in an independent cohort retested over years it followed measured changes with an error of 3.6, so the app only calls a change beyond that.`; },
    s: ['Nes BM, et al. Med Sci Sports Exerc. 2011;43:2024–30', 'Peterman JE, et al. J Am Heart Assoc. 2020;9:e015117', 'Kodama S, et al. JAMA. 2009;301:2024–35'] },
  rhrrisk: { t: 'Resting heart rate and risk', lv: 2, g: 'Meta-analysis of 46 cohorts, 1.25 million people',
    b: () => 'Across 46 prospective studies, each 10 beats a minute higher resting heart rate went with 9% higher all-cause mortality (95% CI 7–12%), independent of the usual risk factors. Against the lowest band, 60–80 bpm carried 12% more risk and over 80 bpm 45% more.<br><br>Resting heart rate falls with aerobic training as the heart pumps more per beat. It also rises for days with illness, poor sleep, alcohol and heat, which is why the app uses the median over four weeks on one consistent scale (the strap, or the watch corrected to it), not a single morning.',
    s: ['Zhang D, et al. CMAJ. 2016;188:E53–63'] },
  sleepdur: { t: 'How long to sleep', lv: 2, g: 'Meta-analysis of 16 cohorts, 1.38 million people; consensus statement',
    b: () => 'In pooled prospective studies, sleeping under 7 hours a night went with 12% higher mortality, and over 9 hours with 30% higher. The long-sleep link is thought to be largely illness that makes people sleep longer, not sleep causing harm. The American Academy of Sleep Medicine and Sleep Research Society recommend 7 hours or more for adults.<br><br>The app averages the watch\'s sleep over four weeks: one short night says nothing, a month of them does.',
    s: ['Cappuccio FP, et al. Sleep. 2010;33:585–92', 'Watson NF, et al. Sleep. 2015;38:843–4'] },
  sjl: { t: 'Social jetlag', lv: 2, g: 'Population study, 65,000 adults',
    b: () => { const J = socialJetlag(); return `Social jetlag is the gap between the middle of your sleep on free days and on workdays: the shift your body clock goes through every weekend, as if flying across time zones and back. In a population survey of about 65,000 people, more of it went with a higher BMI beyond what sleep length explained.<br><br>The app takes the middle of each night from the watch, compares the nights ending on Saturday and Sunday mornings with the rest, over six weeks${J.v != null ? `: <b>${J.v.toFixed(1)} hours</b>, weekends ${J.later ? 'later' : 'earlier'} (from ${J.nf} weekend and ${J.nw} weekday nights)` : ''}. Under an hour is small. The fix is a wake-up time on weekends within an hour of weekdays, with morning light.`; },
    s: ['Roenneberg T, et al. Curr Biol. 2012;22:939–43', 'Wittmann M, et al. Chronobiol Int. 2006;23:497–509'] },
  msa: { t: 'Strength training and lifespan', lv: 2, g: 'Meta-analysis of 16 cohorts',
    b: () => { const M = strengthMin(); return `Independent of aerobic activity, muscle-strengthening activity went with 10–17% lower all-cause mortality, heart disease, cancer and diabetes. The curve was J-shaped: the most benefit at about <b>30–60 minutes a week</b>, then fading for mortality at much higher volumes (no harm shown for strength itself). Lifting and cardio together beat either alone.<br><br>The app counts the minutes of your strength workouts over four weeks${M.est ? '; days logged without a timed workout count three minutes per work set, set plus rest' : ''}: <b>${Math.round(M.perWk)} minutes a week</b> on ${r1(M.days)} days.`; },
    s: ['Momma H, et al. Br J Sports Med. 2022;56:755–63'] },
};
